def snake_case(name):
    out = []
    for i, ch in enumerate(name):
        if ch.isupper():
            # 前一个字符是小写/数字，或者后面还有小写字母，才断词
            prev = name[i - 1] if i > 0 else ''
            nxt = name[i + 1] if i + 1 < len(name) else ''
            need_break = i > 0 and (prev.islower() or prev.isdigit() or (nxt.islower() and prev.isupper()))
            if need_break:
                out.append('_')
            out.append(ch.lower())
        else:
            out.append(ch)
    result = ''.join(out)
    while '__' in result:
        result = result.replace('__', '_')
    return result.strip('_')

for n in ('getUserName', 'HTTPServer', 'parseHTML', 'already_snake'):
    print(n, '->', snake_case(n))
